<?php
require_once __DIR__ . '/includes/functions.php'; $u=require_role('lender');$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$institution=trim($_POST['institution_name']??'');$min=max(0,(float)($_POST['min_amount']??0));$max=max(0,(float)($_POST['max_amount']??0));$sector=$_POST['sector']??'all';$years=max(0,(int)($_POST['min_years_operating']??0));if($institution===''||$max<$min)$error=t('Enter an institution name and ensure the maximum amount is at least the minimum.','Saisissez le nom de l’institution et vérifiez que le maximum est supérieur au minimum.');else{$s=$pdo->prepare('INSERT INTO lender_criteria (lender_user_id,institution_name,min_amount,max_amount,sector,min_years_operating,requires_registration,requires_bank_account,other_requirements,is_active) VALUES (?,?,?,?,?,?,?,?,?,?)');$s->execute([$u['id'],$institution,$min,$max,$sector,$years,isset($_POST['requires_registration'])?1:0,isset($_POST['requires_bank_account'])?1:0,trim($_POST['other_requirements']??''),isset($_POST['is_active'])?1:0]);flash('success',t('Lending criteria published.','Critères de prêt publiés.'));redirect('lender_criteria.php');}}
$s=$pdo->prepare('SELECT * FROM lender_criteria WHERE lender_user_id=? ORDER BY created_at DESC');$s->execute([$u['id']]);$rows=$s->fetchAll();$pageTitle=t('Lending criteria','Critères de prêt');require __DIR__.'/includes/header.php';
?>
<div class="dashboard-heading"><div><span class="eyebrow"><?= e(t('LENDER SETUP','CONFIGURATION PRÊTEUR')) ?></span><h1><?= e(t('Define your lending criteria','Définir vos critères de prêt')) ?></h1><p><?= e(t('Clear requirements help CreditReady avoid sending unsuitable businesses your way.','Des exigences claires aident CreditReady à éviter les dossiers inadaptés.')) ?></p></div></div>
<div class="content-two-col"><form class="panel form-card-inner" method="post"><h2><?= e(t('Add a loan product','Ajouter un produit de prêt')) ?></h2><?php if($error): ?><div class="alert alert-error"><?= e($error) ?></div><?php endif; ?><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label><?= e(t('Institution / product name','Nom de l’institution / du produit')) ?><input name="institution_name" required></label><div class="form-grid"><label><?= e(t('Minimum amount (XAF)','Montant minimum (FCFA)')) ?><input type="number" name="min_amount" min="0" value="50000" required></label><label><?= e(t('Maximum amount (XAF)','Montant maximum (FCFA)')) ?><input type="number" name="max_amount" min="0" value="5000000" required></label></div><label><?= e(t('Eligible sector','Secteur admissible')) ?><select name="sector"><?php foreach(['all'=>'All sectors / Tous secteurs','trade'=>'Trade / Commerce','agriculture'=>'Agriculture','crafts'=>'Crafts / Artisanat','transport'=>'Transport','services'=>'Services','food'=>'Food / Alimentation','other'=>'Other / Autre'] as $v=>$l): ?><option value="<?= e($v) ?>"><?= e($l) ?></option><?php endforeach; ?></select></label><label><?= e(t('Minimum years in operation','Ancienneté minimale (années)')) ?><input type="number" name="min_years_operating" min="0" value="0"></label><label class="checkbox-label"><input type="checkbox" name="requires_registration"> <?= e(t('Business must be formally registered','L’entreprise doit être immatriculée')) ?></label><label class="checkbox-label"><input type="checkbox" name="requires_bank_account"> <?= e(t('Business bank account required','Compte bancaire professionnel requis')) ?></label><label><?= e(t('Other requirements (plain language)','Autres exigences (en termes simples)')) ?><textarea name="other_requirements" rows="3"></textarea></label><label class="checkbox-label"><input type="checkbox" name="is_active" checked> <?= e(t('Publish this criteria for matching','Publier ces critères pour la correspondance')) ?></label><button class="btn btn-primary full-width" type="submit"><?= e(t('Save criteria','Enregistrer les critères')) ?></button></form>
<section class="panel"><h2><?= e(t('Published criteria','Critères publiés')) ?></h2><?php if(!$rows): ?><p class="empty-state"><?= e(t('No criteria added yet.','Aucun critère ajouté.')) ?></p><?php else: ?><div class="criteria-list"><?php foreach($rows as $r): ?><article class="criteria-card"><div class="panel-heading"><strong><?= e($r['institution_name']) ?></strong><span class="pill <?= $r['is_active']?'pill-green':'pill-amber' ?>"><?= e($r['is_active']?t('Active','Actif'):t('Paused','En pause')) ?></span></div><p class="amount-range"><?= e(number_format((float)$r['min_amount'],0)) ?> – <?= e(number_format((float)$r['max_amount'],0)) ?> <small>XAF</small></p><p><?= e($r['sector']==='all'?t('All sectors','Tous secteurs'):$r['sector']) ?> · <?= (int)$r['min_years_operating'] ?> <?= e(t('years minimum','années minimum')) ?></p><small><?= e($r['requires_registration']?t('Registration required','Immatriculation requise'):t('Registration not mandatory','Immatriculation non obligatoire')) ?> · <?= e($r['requires_bank_account']?t('Bank account required','Compte bancaire requis'):t('Bank account not mandatory','Compte bancaire non obligatoire')) ?></small><?php if($r['other_requirements']): ?><p><?= e($r['other_requirements']) ?></p><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></section></div>
